/**
 * Structured, privacy-safe logging: one JSON object per line.
 *
 * Logs must never contain message content, emails, user ids, tokens or keys. As a safety net,
 * {@link sanitizeLogFields} drops any field whose name contains a sensitive word and redacts
 * string values that look like emails, JWTs or bearer tokens. Pass only counters, codes, ids
 * generated by the function itself (such as `request_id`) and enum-like strings.
 */
import { type Clock, systemClock } from "./clock.ts";

export type LogValue = string | number | boolean | null | undefined;
export type LogFields = Readonly<Record<string, LogValue>>;
export type LogLevel = "info" | "warn" | "error";
/** Receives one serialised JSON line. */
export type LogSink = (level: LogLevel, line: string) => void;

/** Writes info to stdout and warnings/errors to stderr. */
export const consoleSink: LogSink = (level: LogLevel, line: string): void => {
  if (level === "error") console.error(line);
  else if (level === "warn") console.warn(line);
  else console.log(line);
};

/**
 * Name segments that mark a field as sensitive. Field names are split on `_`, `-`, `.` and
 * camelCase boundaries, so `user_id`, `userId` and `access_token` are dropped while
 * `input_tokens` and `request_id` are kept.
 */
export const SENSITIVE_KEY_SEGMENTS: ReadonlySet<string> = new Set([
  "user",
  "uid",
  "sub",
  "email",
  "mail",
  "phone",
  "name",
  "ip",
  "jwt",
  "token",
  "authorization",
  "auth",
  "cookie",
  "password",
  "secret",
  "key",
  "apikey",
  "content",
  "text",
  "prompt",
  "message",
  "messages",
  "body",
  "title",
  "note",
]);

const MAX_STRING_LENGTH = 200;
const EMAIL_LIKE = /[^\s@]+@[^\s@]+\.[^\s@]+/;
const JWT_LIKE = /\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/;
const SECRET_LIKE =
  /\b(bearer\s+\S+|sk-[A-Za-z0-9_-]{8,}|AIza[A-Za-z0-9_-]{20,}|re_[A-Za-z0-9]{16,})/i;

/** True when a field name contains a {@link SENSITIVE_KEY_SEGMENTS} segment. */
export function isSensitiveLogKey(key: string): boolean {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .some((segment) => SENSITIVE_KEY_SEGMENTS.has(segment));
}

/** Applies the redaction rules described in the module docs. */
export function sanitizeLogFields(
  fields: LogFields,
): Record<string, string | number | boolean | null> {
  const out: Record<string, string | number | boolean | null> = {};
  for (const [key, value] of Object.entries(fields)) {
    if (value === undefined || isSensitiveLogKey(key)) continue;
    if (typeof value === "number") {
      out[key] = Number.isFinite(value) ? value : null;
    } else if (typeof value === "string") {
      if (EMAIL_LIKE.test(value) || JWT_LIKE.test(value) || SECRET_LIKE.test(value)) {
        out[key] = "[redacted]";
      } else {
        // deno-lint-ignore no-control-regex
        const clean = value.replace(/[\u0000-\u001f\u007f]+/g, " ");
        out[key] = clean.length > MAX_STRING_LENGTH ? clean.slice(0, MAX_STRING_LENGTH) : clean;
      }
    } else {
      out[key] = value;
    }
  }
  return out;
}

/** A logger bound to one function name. */
export interface Logger {
  info(fields: LogFields): void;
  warn(fields: LogFields): void;
  error(fields: LogFields): void;
}

/** Options for {@link createLogger}. */
export interface LoggerOptions {
  sink?: LogSink;
  clock?: Clock;
}

/**
 * Creates a logger that writes `{"ts","level","fn",...fields}` lines. `fn`, `ts` and `level`
 * cannot be overridden by fields.
 */
export function createLogger(fn: string, options: LoggerOptions = {}): Logger {
  const sink = options.sink ?? consoleSink;
  const clock = options.clock ?? systemClock;
  const write = (level: LogLevel, fields: LogFields): void => {
    const line = JSON.stringify({
      ...sanitizeLogFields(fields),
      ts: new Date(clock.now()).toISOString(),
      level,
      fn,
    });
    try {
      sink(level, line);
    } catch {
      // Logging must never break a request.
    }
  };
  return {
    info: (fields) => write("info", fields),
    warn: (fields) => write("warn", fields),
    error: (fields) => write("error", fields),
  };
}

/** A logger that discards everything (tests). */
export const silentLogger: Logger = { info() {}, warn() {}, error() {} };

/**
 * Returns a safe label for an unknown error: its class name only. Error messages can contain
 * user data or upstream payloads, so they are never logged.
 */
export function errorName(err: unknown): string {
  if (err instanceof Error) return err.name || "Error";
  if (err === null) return "null";
  return typeof err;
}

/** Generates a request id (UUID v4). */
export function newRequestId(): string {
  return crypto.randomUUID();
}
